<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$db->beginTransaction();try{$n=$db->exec("UPDATE invoices SET status='overdue' WHERE balance_due>0 AND due_date<CURDATE() AND status IN ('sent','partially_paid')");$rows=$db->query("SELECT i.*,COALESCE(c.email,l.email) email,COALESCE(c.name,l.name) client_name FROM invoices i LEFT JOIN clients c ON c.id=i.client_id LEFT JOIN leads l ON l.id=i.lead_id WHERE i.balance_due>0 AND i.due_date IS NOT NULL AND i.due_date<=DATE_ADD(CURDATE(),INTERVAL 3 DAY) AND i.status NOT IN ('paid','cancelled')")->fetchAll();foreach($rows as $r){$type=((string)$r['due_date']<date('Y-m-d'))?'overdue':'upcoming_due';$check=$db->prepare('SELECT id FROM invoice_reminders WHERE invoice_id=? AND reminder_type=? AND sent_at>=CURDATE() LIMIT 1');$check->execute([$r['id'],$type]);if(!$check->fetch()){$db->prepare('INSERT INTO invoice_reminders(invoice_id,reminder_type) VALUES(?,?)')->execute([$r['id'],$type]);$db->prepare('INSERT INTO invoice_events(invoice_id,event_type,description) VALUES(?,?,?)')->execute([$r['id'],'reminder_queued',ucfirst(str_replace('_',' ',$type)).' reminder queued for '.$r['email']]);}}$db->commit();echo json_encode(['ok'=>true,'overdue_updated'=>$n,'reminders'=>$rows?count($rows):0]).PHP_EOL;}catch(Throwable $e){$db->rollBack();fwrite(STDERR,$e->getMessage().PHP_EOL);exit(1);}